import Link from 'next/link';
import { api, getMe, getLang } from '@/lib/api';
import { tr, type T } from '@/lib/i18n';
import { money, moneyShort, dateTime, date, STATUS, DEAL, locale } from '@/lib/format';
import { ActionButton, ActionForm, PatchSelect, Toggle, BagCreate } from '@/components/client';
import { AccessManager, CreateApiKey, CopyField, Icon } from '@/components/access';
import { ImportBox, BuyerFinder, ListingSwitch, DoNotContact, WorkspaceTabs } from '@/components/buyers';
export async function generateMetadata() { const t = tr(await getLang()); return { title: `${t('Staff workspace')} | Maasland & Partners`, robots: { index: false, follow: false } }; }

/* Three kinds of user: developer (everything, incl. CRM & API), admin (runs the workspace, invites investors), investor. */
const TABS: [string, string][] = [['buyers', 'Buyers'], ['outreach', 'Outreach'], ['overview', 'Overview'], ['investors', 'Investors'], ['offers', 'Offers & deals'], ['messages', 'Messages'], ['bids', 'Bid rounds'], ['processes', 'Deal processes'],['acquisitions', 'Acquisitions'], ['listings', 'Listings'], ['compliance', 'Compliance'], ['automation', 'Automation']];
const LEAD_STAGES: [string, string][] = [['new', 'New'], ['contacted', 'Contacted'], ['valuation', 'Valuation'], ['offer_made', 'Offer made'], ['under_contract', 'Under contract'], ['acquired', 'Acquired'], ['lost', 'Lost']];
const RULES: [string, string, string][] = [['scoring', 'Score every new lead', 'Rates each request 0–100 from type, verification, offer level and detail.'], ['followups', 'Schedule follow-ups', 'Due within 4 hours for hot leads, next day for others.'], ['emails', 'Draft confirmation emails', 'Writes to the outbox; an email provider sends them in production.'], ['matches', 'Match new listings to buy boxes', 'On publish; Investor Pro first for off-market, verified 48 h later (scheduled job).'], ['priceAlerts', 'Alert buyers to price drops', 'Savers and newly fitting saved searches get an alert.']];

export default async function Admin({ searchParams }: { searchParams: Promise<Record<string, string | undefined>> }) {
  const me = await getMe(); const sp = await searchParams; const dev = me.user?.role === 'developer'; const { tab = 'access' } = sp; const t = tr(await getLang());
  const ws = me.user?.staff ? await api('/admin/workspace') : null; const states: any[] = ws?.ok ? ws.data.tabs : TABS.map(([key, label]) => ({ key, label, visible: true }));
  /* the developer chooses which sections admins see (Settings); developers always see every section, hidden ones dimmed */
  const tabs: [string, string, boolean][] = [...states.slice(0, 1).map(t => [t.key, t.label, false] as [string, string, boolean]), ...(dev ? [['integrations', 'CRM & API', false], ['settings', 'Settings', false]] as [string, string, boolean][] : []),
    ...states.slice(1).filter(t => dev || t.visible).map(t => [t.key, t.label, !t.visible] as [string, string, boolean])];
  const blocked = !dev && states.some(t => t.key === tab && !t.visible);
  if (!me.user?.staff) return <section className="page-heading"><p className="eyebrow">{t('STAFF WORKSPACE')}</p><h1>{t('Staff only.')}</h1><p>{t('Log in with a staff account (for example admin@demo.nl). Staff accounts always use two-factor login.')}</p><Link className="btn navy" href="/login?next=/admin">{t('Log in ↗')}</Link></section>;
  return <><section className="page-heading workspace-heading"><p className="eyebrow">{t('STAFF WORKSPACE')} · {t(`${me.user.role}||role`).toUpperCase()} · {me.user.name}</p><h1>{t('Behind the')} <em>{t('offering.')}</em></h1><p>{t('Admins run the workspace and invite investors, deciding per person which properties and tools they see. Developers can also create admin accounts and manage the CRM & API connection.')}</p></section>
    <section className="section ws">{dev && <div className="ws-tabs" role="tablist">{tabs.map(([k, l, off]) => <Link key={k} role="tab" aria-selected={tab === k} className={off ? 'off' : undefined} data-hidden={t('hidden')} title={off ? t('Hidden for admins') : undefined} href={`/admin?tab=${k}`} scroll={false}>{t(l)}</Link>)}</div>}<div className="ws-body">{blocked ? <div className="empty"><p>{t('This section is switched off for admins. A developer can switch it on under Settings.')}</p></div> : await ((tab === 'messages' ? () => Messages(sp) : tab === 'access' ? () => Access(me.user!.id) : tab === 'buyers' ? () => Buyers(sp) : tab === 'outreach' ? () => Outreach(sp) : tab === 'settings' && dev ? () => Settings() : null) || ({ integrations: Integrations, overview: Overview, investors: Investors, offers: Offers, messages: Messages, bids: Bids, processes: Processes, acquisitions: Acquisitions, listings: Listings, compliance: Compliance, automation: Automation } as any)[tab] || (() => Access(me.user!.id)))()}</div></section></>;
}
const lang = async () => tr(await getLang());
const Denied = ({ r, t }: { r: any; t: T }) => <div className="empty"><p className="form-error">{r.data?.message || t('Not allowed for your role.')}</p></div>;
const conds = (t: T, c: string[]) => c.map(x => t(x)).join(', ');
async function Overview() {
  const t = await lang();
  const r = await api('/admin/overview'); if (!r.ok) return <Denied r={r} t={t} />; const d = r.data; const max = Math.max(1, ...d.funnel.map((f: any) => f[1]));
  return <><div className="kpi-grid">{d.kpis.map((k: any) => <div key={k.label} className="kpi"><span>{t(k.label)}</span><b>{k.value}</b><small>{t('Target: {v}', { v: t(String(k.target)) })}</small></div>)}</div><p className="fine-print">{t(d.note)}</p>
    <div className="two-panels" style={{ marginTop: 24 }}><div className="panel"><p className="eyebrow">{t('FUNNEL')}</p><h2>{t('Views to deals.')}</h2>{d.funnel.map(([l, v]: [string, number]) => <div key={l} className="funnel-row"><span>{t(l)}</span><div className="t"><i style={{ width: Math.max(2, v / max * 100) + '%' }} /></div><b>{v}</b></div>)}</div>
      <div className="panel"><p className="eyebrow">{t('ACQUISITION PIPELINE')}</p><h2>{money(d.pipelineValue)}</h2><p>{t('Estimated value of active seller leads.')}</p>{d.leadStages.map(([s, n]: [string, number]) => <div key={s} className="funnel-row"><span>{t(`${s.replace('_', ' ')}||lead`)}</span><div className="t"><i style={{ width: Math.min(100, n * 20) + '%' }} /></div><b>{n}</b></div>)}</div></div></>;
}
async function Investors() {
  const t = await lang();
  const r = await api('/admin/investors'); if (!r.ok) return <Denied r={r} t={t} />;
  return <><div className="section-heading"><div><p className="eyebrow">{t('BUY-SIDE CRM')}</p><h2>{t('Investors.')}</h2></div><span className="muted-small">{t('Lead score grows with views, downloads, NDAs, offers and bids')}</span></div><div className="table-wrap" tabIndex={0}><table><thead><tr><th>{t('Investor')}</th><th>{t('Type')}</th><th>{t('Country')}</th><th>{t('Tier')}</th><th>KYC</th><th>{t('Risk')}</th><th>{t('Lead score')}</th><th>{t('Last activity')}</th><th>{t('Manager')}</th></tr></thead><tbody>{r.data.map(u => <tr key={u.id}><td><b>{u.name}</b><small>{u.email}</small></td><td>{t(u.type)}</td><td>{u.country}</td><td><span className={`tier-pill tier-${u.tier}`}>{t(u.tierLabel)}</span></td><td>{t(`${u.kyc}||kyc`)}</td><td><span className={`risk ${u.risk}`}>{t(`${u.risk}||risk`)}</span></td><td><span className="score-mini"><i style={{ width: u.leadScore + '%' }} /></span>{u.leadScore}</td><td>{u.lastActivity}<small>{dateTime(u.lastAt, t)}</small></td><td>{u.manager}</td></tr>)}</tbody></table></div></>;
}
async function Offers() {
  const t = await lang();
  const [o, d, e] = await Promise.all([api('/admin/offers'), api('/admin/deals'), api('/admin/enquiries')]); if (!o.ok) return <Denied r={o} t={t} />;
  return <><div className="section-heading"><div><p className="eyebrow">{t('ADMIN DEAL ROOM')}</p><h2>{t('Offers to review.')}</h2></div></div>{o.data.length ? <div className="table-wrap" tabIndex={0}><table><thead><tr><th>{t('Investor')}</th><th>{t('Property')}</th><th>{t('Amount')}</th><th>{t('vs asking')}</th><th>{t('Conditions')}</th><th>{t('Transfer')}</th><th>{t('Proof')}</th><th>{t('Status')}</th><th>{t('Decision')}</th></tr></thead><tbody>{o.data.map(x => <tr key={x.id}><td><b>{x.investor}</b>{x.leadBand && <span className={`heat ${x.leadBand}`}>{t(`${x.leadBand}||band`)} · {x.leadScore}</span>}<small>{t('Follow up {date}', { date: dateTime(x.followupAt, t) })}</small></td><td>{x.listing === 'General' ? t('General||listing') : x.listing}</td><td>{money(x.amount)}</td><td>{x.vsAsking}%</td><td>{conds(t, x.conditions) || t('None')}</td><td>{x.transferDate}</td><td>{x.proofFileName ? <a href={`/api/admin/offers/${x.id}/proof`} target="_blank">📎 {x.proofFileName}</a> : '—'}</td><td><span className={`pill os-${x.status}`}>{t(x.status)}</span>{x.counterAmount ? <small>{t('counter {amount}', { amount: money(x.counterAmount) })}</small> : null}</td>
    <td>{['submitted', 'in_review'].includes(x.status) ? <div className="row tight"><ActionButton url={`/api/admin/offers/${x.id}/decision`} json={{ decision: 'accepted' }} label={t('Accept')} className="btn small navy" /><ActionButton url={`/api/admin/offers/${x.id}/decision`} json={{ decision: 'countered', counterAmount: Math.round(x.amount * 1.03 / 1000) * 1000 }} label={t('Counter {amount}', { amount: money(Math.round(x.amount * 1.03 / 1000) * 1000) })} /><ActionButton url={`/api/admin/offers/${x.id}/decision`} json={{ decision: 'rejected' }} label={t('Reject')} /></div> : '—'}</td></tr>)}</tbody></table></div> : <div className="empty"><p>{t('No offers yet. Log in as verified@demo.nl and make one.')}</p></div>}
    {d.data?.length > 0 && <><div className="section-heading" style={{ marginTop: 50 }}><div><p className="eyebrow">{t('DEALS')}</p><h2>{t('Deal timelines.')}</h2></div></div>{d.data.map((x: any) => <div key={x.id} className="deal-card"><div className="row between"><div><p className="eyebrow">{x.buyer}</p><h3>{x.listing} · {money(x.price)}</h3></div><ActionButton url={`/api/admin/deals/${x.id}/advance`} label={t('Advance to next stage ↗')} className="btn small navy" /></div><ol className="timeline">{x.stages.map((s: string, i: number) => <li key={s} className={i < x.stage ? 'done' : i === x.stage ? 'cur' : ''}><span />{t(s)}</li>)}</ol></div>)}</>}
    <div className="section-heading" style={{ marginTop: 50 }}><div><p className="eyebrow">{t('VIEWINGS & QUESTIONS')}</p><h2>{t('Requests.')}</h2></div></div>{e.data?.length ? <div className="table-wrap" tabIndex={0}><table><thead><tr><th>{t('Type')}</th><th>{t('From')}</th><th>{t('Property')}</th><th>{t('Details')}</th><th>{t('Lead')}</th><th>{t('Follow up')}</th><th>{t('Status')}</th></tr></thead><tbody>{e.data.map((x: any) => <tr key={x.id}><td>{t(`${x.kind}||enquiry`)}</td><td>{x.name}<small>{x.email}</small></td><td>{x.listing === 'General' ? t('General||listing') : x.listing}</td><td>{x.preferredDate ? `${x.preferredDate} · ${x.format ? t(x.format) : x.format}` : x.message}</td><td>{x.leadBand && <span className={`heat ${x.leadBand}`}>{t(`${x.leadBand}||band`)}</span>}</td><td className={x.followupAt && new Date(x.followupAt) < new Date() && x.status === 'new' ? 'form-error' : ''}>{dateTime(x.followupAt, t)}</td><td><PatchSelect url={`/api/admin/enquiries/${x.id}`} field="status" value={x.status} label={t('Status')} options={[['new', t('New')], ['contacted', t('Contacted')], ['viewing_scheduled', t('Viewing scheduled')], ['closed', t('Closed||enquiry')]]} /></td></tr>)}</tbody></table></div> : <p>{t('No viewing requests or questions yet.')}</p>}</>;
}
async function Bids() {
  const t = await lang();
  const r = await api('/admin/bid-rounds'); if (!r.ok) return <Denied r={r} t={t} />;
  return <>{r.data.map(b => <div key={b.id} className="panel bid-admin"><div className="row between"><div><p className="eyebrow">{t('BID ROUND')}</p><h2>{b.listing}</h2><p>{t('Closes {date} · minimum {min} · {n} bids', { date: dateTime(b.closesAt, t), min: money(b.minBid), n: b.bidCount })}</p></div><span className={`pill st-${b.status}`}>{t(`${b.status}||round`)}</span></div>
    {b.status === 'open' ? <><div className="note">{t('Bids stay sealed: nobody, including staff, sees amounts until the deadline. A background job closes the round automatically at the deadline.')}</div><div style={{ marginTop: 18 }}><ActionButton url={`/api/admin/bid-rounds/${b.id}/close`} label={t('Close the round now (demo) ↗')} className="btn navy" confirmText={t('Close this bid round now? Bids will be locked.')} /></div></>
      : <><div className="table-wrap" tabIndex={0}><table><thead><tr><th>{t('Rank')}</th><th>{t('Bidder')}</th><th>{t('Amount')}</th><th>{t('vs minimum')}</th><th>{t('Conditions')}</th><th>{t('Proof')}</th></tr></thead><tbody>{b.ranking.map((x: any, i: number) => <tr key={x.offerId} className={i === 0 ? 'top' : ''}><td>{i + 1}</td><td>{x.bidder}</td><td><b>{money(x.amount)}</b></td><td>+{((x.amount / b.minBid - 1) * 100).toFixed(1)}%</td><td>{conds(t, x.conditions)}</td><td>{x.proof ? '📎' : '—'}</td></tr>)}</tbody></table></div>{b.status === 'closed' ? <ActionButton url={`/api/admin/bid-rounds/${b.id}/award`} label={t('Award to the highest bidder and notify all ↗')} className="btn navy" /> : <p><b>{t('Awarded.')}</b> {t('Winner and unsuccessful bidders were notified.')}</p>}</>}</div>)}</>;
}
async function Processes() {
  const t = await lang();
  const r = await api('/admin/processes'); if (!r.ok) return <Denied r={r} t={t} />;
  return <>{r.data.map((p: any) => <div key={p.id} className="panel bid-admin"><div className="row between wrap"><div><p className="eyebrow">{t('PRIVATE DEAL ROOM · STAGE {a}/{b}', { a: p.stage + 1, b: p.stages })}</p><h2><Link href={`/listings/${p.slug}?tab=process`}>{p.name}</Link></h2><p>{t('Guide {amount}', { amount: money(p.askingPrice) })} · {t(p.stageLabel)}{p.nextDeadline ? ` · ${t(p.nextDeadline.label)} ${date(p.nextDeadline.at, t)}` : ''} · {t('shortlist {n}', { n: p.shortlist })}</p></div>
      {p.stage < p.stages - 1 && <ActionButton url={`/api/admin/processes/${p.id}/advance`} label={t('Move to “{stage}” ↗', { stage: t(p.stagesList[p.stage + 1].label) })} className="btn navy small" confirmText={p.stagesList[p.stage + 1].key === 'shortlist' ? t('Close indicative bids and shortlist the top 3? All bidders are notified.') : t('Move the process to the next stage?')} />}</div>
    <ol className="stage-line compact">{p.stagesList.map((s: any, i: number) => <li key={s.key} className={i < p.stage ? 'done' : i === p.stage ? 'current' : 'next'}><span>{i < p.stage ? '✓' : i === p.stage ? '●' : ''}</span><b>{t(s.label)}</b>{s.deadline && <small>{date(s.deadline, t)}</small>}</li>)}</ol>
    {p.bids.length > 0 ? <div className="table-wrap" tabIndex={0}><table><thead><tr><th>{t('Bidder')}</th><th>{t('Type')}</th><th>{t('Amount')}</th><th>{t('vs guide')}</th><th>{t('Financing')}</th><th>{t('Terms')}</th><th>{t('Received')}</th></tr></thead><tbody>{p.bids.map((b: any) => <tr key={b.id}><td><b>{b.bidder}</b></td><td>{t(b.status)}</td><td>{b.amount === null ? t('Hidden for your role') : money(b.amount)}</td><td>{b.vsGuide === null ? '—' : b.vsGuide + '%'}</td><td>{b.financing ? t(b.financing) : b.financing}</td><td>{conds(t, b.conditions)}</td><td>{dateTime(b.at, t)}</td></tr>)}</tbody></table></div> : <p className="muted-small">{t('No bids yet.')}</p>}
    <p className="eyebrow" style={{ marginTop: 20 }}>{t('OPEN Q&A · {n}', { n: p.openQuestions.length })}</p>{p.openQuestions.map((q: any) => <div key={q.id} className="qa-admin"><p><span className="pill">{t(q.category)}</span> {q.question} <small>{dateTime(q.at, t)}</small></p><ActionForm action={`/api/admin/qa/${q.id}/answer`} className="msg-compose" success={t('Answered. All parties see it, anonymised.')} submitLabel={t('Publish answer ↗')}><textarea name="answer" required minLength={5} maxLength={4000} placeholder={t('Answer for all parties in the deal room')} /></ActionForm></div>)}</div>)}</>;
}
async function Acquisitions() {
  const t = await lang();
  const r = await api('/admin/leads'); if (!r.ok) return <Denied r={r} t={t} />;
  const stages: [string, string][] = LEAD_STAGES.map(([k, l]) => [k, t(l)]);
  return <><div className="section-heading"><div><p className="eyebrow">{t('SELL-SIDE PIPELINE')}</p><h2>{t('Acquisitions.')}</h2></div><span className="muted-small">{t('Leads from “Sell to us”, brokers, lists and referrals')}</span></div>
    <div className="kanban seven">{stages.map(([st, label]) => { const items = r.data.filter(l => l.stage === st); return <div key={st} className="kcol"><h3>{label}<span>{items.length}</span></h3>{items.map(l => <div key={l.id} className="lead"><span className="heat Cold">{t(l.source)}</span><h4>{l.address}</h4><p>{t(l.propertyType)} · {t('{n} units', { n: l.units })}</p><p>{t('Asking {amount}', { amount: money(l.askingPrice) })}{l.estValue ? ` · ${t('est. {amount}', { amount: money(l.estValue) })}` : ''}</p><p className="due">{l.ownerName}{l.contactName ? ` · ${l.contactName}` : ''}</p><PatchSelect url={`/api/admin/leads/${l.id}`} field="stage" value={l.stage} options={stages} label={t('Stage')} /></div>)}{!items.length && <p className="kempty">—</p>}</div>; })}</div>
    <ActionForm action="/api/admin/leads" numbers={['units', 'askingPrice']} className="panel" success={t('Lead added.')} submitLabel={t('Add to pipeline ↗')}><p className="eyebrow">{t('ADD A LEAD')}</p><div className="form-grid four"><label>{t('Address')}<input name="address" required minLength={3} /></label><label>{t('Type')}<select name="propertyType">{['Residential portfolio', 'Apartment building', 'Single home', 'Mixed-use'].map(x => <option key={x} value={x}>{t(x)}</option>)}</select></label><label>{t('Units')}<input name="units" type="number" min={1} defaultValue={6} /></label><label>{t('Asking (€)')}<input name="askingPrice" type="number" min={0} /></label><label>{t('Source')}<select name="source">{['Broker', 'Referral', 'List · box 3 landlords', 'Direct mail'].map(x => <option key={x} value={x}>{t(x)}</option>)}</select></label></div><p className="fine-print">{t('Contact private owners by direct mail; cold calls and e-mails to consumers are restricted under Dutch telecom law.')}</p></ActionForm></>;
}
async function Listings() {
  const t = await lang();
  const [r, c] = await Promise.all([api('/admin/listings'), api('/admin/config')]); if (!r.ok) return <Denied r={r} t={t} />;
  const drafts = r.data.filter(l => l.status === 'draft');
  return <><div className="two-panels"><BagCreate /><div className="panel"><p className="eyebrow">{t('DRAFTS & PUBLISHING')}</p><h2>{t('Ready to go live.')}</h2>{drafts.length ? drafts.map(l => <div key={l.id} className="draft-row"><div><h3>{l.name}</h3><p>{l.city} · {money(l.askingPrice)} · {t(DEAL[l.dealType])}</p></div><ActionButton url={`/api/admin/listings/${l.id}/publish`} label={t('Publish & match ↗')} className="btn navy small" /></div>) : <p>{t('No drafts. Create one with the BAG lookup. Publishing runs buy-box matching.')}</p>}</div></div>
    <div className="section-heading" style={{ marginTop: 50 }}><div><p className="eyebrow">{t('INVENTORY')}</p><h2>{t('Status and pricing.')}</h2></div></div><div className="table-wrap" tabIndex={0}><table><thead><tr><th>{t('Listing')}</th><th>{t('Buyers')}</th><th>{t('Deal type')}</th><th>{t('Published')}</th><th>{t('Price k.k.')}</th><th>{t('New price')}</th><th>{t('Status')}</th></tr></thead><tbody>{r.data.map(l => <tr key={l.id}><td><b>{l.status === 'draft' ? l.name : <Link href={`/listings/${l.slug}`}>{l.name}</Link>}</b><small>{l.city}</small></td><td>{!['sold', 'withdrawn', 'draft'].includes(l.status) ? <Link className="btn small navy find-btn" href={`/admin?tab=buyers&find=${l.id}`}><Icon name="users" />{t('Find buyers')}</Link> : <span className="muted-small">—</span>}</td><td>{t(DEAL[l.dealType])}</td><td>{date(l.publishedAt, t)}</td><td>{money(l.askingPrice)}{l.previousPrice ? <small><s>{money(l.previousPrice)}</s></small> : null}</td><td><ActionForm action={`/api/admin/listings/${l.id}`} method="PATCH" numbers={['askingPrice']} className="inline-form" success={t('Price updated; alerts sent.')} submitLabel={t('Update')}><input name="askingPrice" type="number" min={100000} step={1000} defaultValue={l.askingPrice} aria-label={t('New price')} /></ActionForm></td><td><PatchSelect url={`/api/admin/listings/${l.id}`} field="status" value={l.status} label={t('Status')} options={Object.entries(STATUS).map(([k, v]) => [k, t(v)] as [string, string])} /></td></tr>)}</tbody></table></div>
    {c.ok && <ActionForm action="/api/admin/config" method="PUT" numbers={c.data.map((x: any) => x.key)} className="panel" success={t('Config saved. Calculators use the new values.')} submitLabel={t('Save config ↗')}><p className="eyebrow">{t('CONFIG TABLE · ADMIN ONLY')}</p><h2>{t('Rates and fees.')}</h2><p className="fine-print">{t('Calculators read these values; change them when the law changes.')}</p>{c.data.map((x: any) => <label key={x.key} className="cfg-row"><span>{t(x.label)}<small>{t('valid from {date}', { date: x.validFrom })}</small></span><span className="row tight"><input name={x.key} type="number" step="0.1" min={0} defaultValue={x.value} />{t(`${x.unit}||unit`)}</span></label>)}</ActionForm>}</>;
}
async function Compliance() {
  const t = await lang();
  const [k, a, o] = await Promise.all([api('/admin/kyc'), api('/admin/audit?limit=60'), api('/admin/offers')]); if (!k.ok) return <Denied r={k} t={t} />;
  const pending = k.data.filter(x => x.status === 'pending');
  return <><div className="section-heading"><div><p className="eyebrow">{t('WWFT · CUSTOMER DUE DILIGENCE')}</p><h2>{t('Verification queue.')}</h2></div><span className="muted-small">{t('High risk needs enhanced due diligence notes before approval')}</span></div>
    {pending.length ? pending.map(x => <div key={x.id} className="panel kyc-case"><div className="row between"><div><h3>{x.name} <span className={`risk ${x.risk}`}>{t(`${x.risk}||risk`)}</span></h3><p>{t(x.type)} · {x.country} · {x.email} · {t('submitted {date}', { date: dateTime(x.submittedAt, t) })}</p><p className="muted-small">{x.checks}{x.pep ? ` · ${t('PEP: yes')}` : ''} · {t('ticket {amount}', { amount: money(x.ticket) })}</p><p><a href={`/api/admin/kyc/${x.id}/file/id`} target="_blank">📎 {x.idFileName}</a> · <a href={`/api/admin/kyc/${x.id}/file/proof`} target="_blank">📎 {x.proofFileName}</a></p></div></div>
      <ActionForm action={`/api/admin/kyc/${x.id}/decision`} className="inline-form wide" success={t('Decision recorded.')}><label>{t('Notes')}{x.risk === 'high' ? t(' (required for approval)') : ''}<input name="notes" maxLength={500} placeholder={x.risk === 'high' ? t('EDD: source of funds verified…') : t('Optional')} /></label><button className="btn small navy" name="decision" value="approved">{t('Approve')}</button><button className="btn small outline" name="decision" value="rejected">{t('Reject')}</button></ActionForm></div>) : <div className="empty"><p>{t('The queue is empty.')}</p></div>}
    <div className="two-panels" style={{ marginTop: 40 }}><div className="panel"><p className="eyebrow">{t('UNUSUAL TRANSACTIONS')}</p><h2>{t('Flag for review.')}</h2>{(o.data || []).map((x: any) => <div key={x.id} className="document-row"><span>{x.investor} · {x.listing}<small>{money(x.amount)} · {conds(t, x.conditions)}</small></span><ActionButton url={`/api/admin/offers/${x.id}/flag`} label={x.flagged ? t('Flagged ✓') : t('Flag')} className={`btn small ${x.flagged ? 'navy' : 'outline'}`} /></div>)}<p className="fine-print">{t('Supports reporting to FIU-Nederland within the legal deadline.')}</p></div>
      <div className="panel"><p className="eyebrow">{t('AUDIT LOG · APPEND-ONLY')}</p><h2>{t('Who did what.')}</h2>{a.ok ? <ul className="log">{a.data.map((e: any) => <li key={e.id}><b>{e.action}</b> · {e.objectType}{e.meta && Object.keys(e.meta).length ? ' · ' + Object.entries(e.meta).map(([k, v]) => `${k}: ${v}`).join(', ') : ''}<small>{e.actorLabel} · {dateTime(e.at, t)}{e.ip ? ' · ' + e.ip : ''}</small></li>)}</ul> : <p>{a.data?.message}</p>}</div></div></>;
}
async function Messages(sp: { investor?: string; listing?: string } = {}) {
  const t = await lang();
  const r = await api('/admin/messages'); if (!r.ok) return <Denied r={r} t={t} />; const list: any[] = r.data.threads;
  const cur = sp.investor ? { investorId: sp.investor, slug: sp.listing || 'general' } : list[0]; if (!cur) return <div className="empty"><p>{t('No conversations yet.')}</p></div>;
  const th = await api(`/admin/messages/thread?investor=${cur.investorId}&listing=${encodeURIComponent(cur.slug)}`); const thr = th.ok ? th.data : null;
  return <><div className="ws-head"><h2>{t('Messages')}</h2><p className="muted-small">{t('{n} unread · investors write from a listing or My account. Sales and admin reply; compliance can read.', { n: r.data.unread })}</p></div>
    <div className="msg-layout ws-msg"><nav className="msg-threads" aria-label={t('Conversations')}>{list.map(x => { const on = x.investorId === cur.investorId && x.slug === cur.slug; return <Link key={x.investorId + x.slug} scroll={false} href={`/admin?tab=messages&investor=${x.investorId}&listing=${x.slug}`} className={on ? 'on' : ''}><b>{x.investorName}{x.unreadForStaff > 0 && !on && <i className="dot">{x.unreadForStaff}</i>}</b><span>{x.slug === 'general' ? t(x.listingName) : x.listingName} · {x.last}</span><small>{x.companyName ? x.companyName + ' · ' : ''}{dateTime(x.lastAt, t)}</small></Link>; })}</nav>
      <div className="msg-pane">{!thr ? <Denied r={th} t={t} /> : <><div className="msg-head"><div><p className="eyebrow">{thr.investor.pro ? 'INVESTOR PRO' : thr.investor.verified ? t('VERIFIED INVESTOR') : t('FREE MEMBER')} · {thr.investor.email}</p><h2>{thr.investor.name}{thr.investor.companyName ? ` · ${thr.investor.companyName}` : ''}</h2><p className="muted-small">{thr.listing.slug === 'general' ? t(thr.listing.name) : <Link href={`/listings/${thr.listing.slug}`}>{thr.listing.name} ↗</Link>}</p></div></div>
        <ol className="msg-list">{thr.messages.map((m: any) => <li key={m.id} className={m.fromStaff ? 'me' : 'them'}><p>{m.body}</p><small>{m.sender} · {dateTime(m.at, t)}</small></li>)}</ol>
        {thr.canReply ? <ActionForm action="/api/admin/messages" className="msg-compose" success={t('Reply sent. The investor gets an alert.')} submitLabel={t('Reply ↗')}><input type="hidden" name="investorId" value={thr.investor.id} /><input type="hidden" name="listing" value={thr.listing.slug} /><textarea name="body" aria-label={t('Reply')} required minLength={2} maxLength={4000} placeholder={t('Reply to {name}…', { name: thr.investor.name.split(' ')[0] })} /></ActionForm> : <p className="note">{t('Read-only for your role.')}</p>}</>}</div></div></>;
}
async function Automation() {
  const t = await lang();
  const [r, out, jobs] = await Promise.all([api('/admin/automation'), api('/admin/outbox'), api('/admin/jobs')]); if (!r.ok) return <Denied r={r} t={t} />;
  const on = (k: string) => r.data.settings.find((s: any) => s.key === k)?.enabled !== false;
  return <><div className="two-panels"><div className="panel"><p className="eyebrow">{t('AUTOMATION RULES · ADMIN ONLY')}</p><h2>{t('Less manual work.')}</h2>{RULES.map(([k, name, d]) => <div key={k} className="rule"><span><b>{t(name)}</b><small>{t(d)}</small><span className="runs">{t('{n} runs', { n: r.data.runs[k] || 0 })}</span></span><Toggle url={`/api/admin/automation/${k}`} enabled={on(k)} label={t(name)} /></div>)}<div className="row" style={{ marginTop: 16 }}><ActionButton url="/api/admin/jobs/run" label={t('Run due background jobs now')} done={t('Jobs checked.')} /></div></div>
    <div className="panel"><p className="eyebrow">{t('ACTIVITY LOG')}</p><h2>{t('What ran, and when.')}</h2><ul className="log">{r.data.log.map((l: any) => <li key={l.id}><b>{l.rule}</b> · {l.text}<small>{dateTime(l.at, t)}</small></li>)}</ul></div></div>
    <div className="two-panels" style={{ marginTop: 30 }}><div className="panel"><p className="eyebrow">{t('OUTBOX · DRAFTS, NOT SENT')}</p><h2>{t('Emails.')}</h2>{(out.data || []).slice(0, 12).map((m: any) => <details key={m.id} className="document-row"><summary>{m.subject}<small>{t('To {email} · {date}', { email: m.toEmail, date: dateTime(m.createdAt, t) })}</small></summary><p>{m.body}</p></details>)}</div>
      <div className="panel"><p className="eyebrow">{t('SCHEDULED JOBS')}</p><h2>{t('Background queue.')}</h2>{(jobs.data || []).length ? jobs.data!.map((j: any) => <div key={j.id} className="document-row"><span>{j.kind}<small>{t('run at {date} · {status}', { date: dateTime(j.runAt, t), status: t(`${j.status}||job`) })}</small></span></div>) : <p>{t('Bid-round closing runs every 30 seconds. Off-market releases appear here when an off-market listing is published.')}</p>}</div></div></>;
}
async function Access(meId: string) {
  const t = await lang();
  const r = await api('/admin/access'); if (!r.ok) return <Denied r={r} t={t} />;
  return <AccessManager data={r.data} meId={meId} />;
}
async function Integrations() {
  const t = await lang();
  const r = await api('/admin/integrations'); if (!r.ok) return <Denied r={r} t={t} />; const d = r.data;
  const curl = `curl -X POST https://<your-domain>/api/integrations/crm/listings \
  -H "x-api-key: pp_live_…" -H "content-type: application/json" \
  -d @listing.json`;
  return <div className="integrations">
    <div className="access-top"><div><p className="eyebrow">{t('CRM INTEGRATION')}</p><h2>{t('Listings come from the CRM.')}</h2><p className="muted-small">{t('The company CRM pushes every property it buys. The same CRM id updates the same listing; withdrawing removes it from every selection.')}</p></div>
      <ActionButton url="/api/admin/integrations/crm/sample" label={<><Icon name="bolt" />{t('Send a sample listing')}</>} className="btn navy" done={t('Sample listing created from a CRM payload. See it under Listings and in People & access.')} /></div>
    <div className="stat-row"><div><b>{d.crmListings}</b><span>{t('Listings from the CRM')}</span></div><div><b>{d.lastSync ? dateTime(d.lastSync, t) : '—'}</b><span>{t('Last sync')}</span></div><div><b>{d.keys.filter((k: any) => !k.revoked).length}</b><span>{t('Active API keys')}</span></div><div><b>{d.envKey ? t('On') : t('Off')}</b><span>{t('Bootstrap key (PP_CRM_API_KEY)')}</span></div></div>
    <div className="two-panels"><div className="panel"><p className="eyebrow">{t('API KEYS')}</p><h2>{t('Who may push.')}</h2><CreateApiKey />
      {d.keys.length ? <div className="key-list">{d.keys.map((k: any) => <div key={k.id} className={`key-row ${k.revoked ? 'revoked' : ''}`}><span className="in-ic"><Icon name="plug" /></span><div><b>{k.name}</b><small><code>{k.prefix}…</code> · {t('created {date}', { date: date(k.createdAt, t) })} · {k.lastUsedAt ? t('last used {date}', { date: dateTime(k.lastUsedAt, t) }) : t('never used')}</small></div>{k.revoked ? <span className="status-chip expired"><i />{t('Revoked')}</span> : <ActionButton url={`/api/admin/integrations/keys/${k.id}/revoke`} label={t('Revoke')} confirmText={t('Revoke this key? The CRM can no longer push listings with it.')} />}</div>)}</div> : <p className="muted-small">{t('No keys yet. Create one and paste it into the CRM’s webhook settings.')}</p>}</div>
      <div className="panel"><p className="eyebrow">{t('ENDPOINTS')}</p><h2>{t('Three calls.')}</h2><ul className="endpoints"><li><code className="m post">POST</code><code>/api/integrations/crm/listings</code><small>{t('Create or update one listing (or an array of up to 200). Upsert by')} <code>externalId</code>.</small></li><li><code className="m del">DELETE</code><code>/api/integrations/crm/listings/:externalId</code><small>{t('Withdraw a listing everywhere.')}</small></li><li><code className="m get">GET</code><code>/api/integrations/crm/ping</code><small>{t('Check the key.')}</small></li></ul>
        <pre className="code" tabIndex={0}>{curl}</pre><p className="fine-print">{t('Optional')} <code>shareWith</code>: {t('emails of invited people who should see the listing at once. Publishing runs buy-box matching for people who can see it.')}</p></div></div>
    <div className="two-panels"><details className="panel payload"><summary><span><p className="eyebrow">{t('PAYLOAD')}</p><h2>{t('Example listing.json')}</h2></span><span className="text-link">{t('Show')}</span></summary><pre className="code">{JSON.stringify(d.sample, null, 2)}</pre></details>
      <div className="panel"><p className="eyebrow">{t('SYNC LOG')}</p><h2>{t('Recent pushes.')}</h2>{d.log.length ? <ul className="log">{d.log.map((l: any) => <li key={l.id}>{l.text}<small>{dateTime(l.at, t)}</small></li>)}</ul> : <p className="muted-small">{t('Nothing received yet. Try “Send a sample listing”.')}</p>}</div></div>
  </div>;
}

/* ---------- Buyers & outreach ---------- */
const STAGE_LABEL: Record<string, string> = { new: 'New', contacted: 'Contacted', interested: 'Interested', in_talks: 'In talks', customer: 'Customer', not_interested: 'Not interested' };
const SEG: Record<string, string> = { 'recente koper': 'Recent buyer', 'lang in bezit': 'Long-term holder', gemengd: 'Mixed', midden: 'Middle' };
const USE: Record<string, string> = { residential: 'Residential', retail: 'Retail', office: 'Office', industrial: 'Industrial', hospitality: 'Hotel & lodging', healthcare: 'Healthcare', education: 'Education', assembly: 'Assembly', other: 'Other' };
const pct = (v?: number | null) => v === null || v === undefined ? '—' : Math.round(v * 100) + '%';
const seg = (t: T, s?: string | null) => s ? (SEG[s] ? t(`${SEG[s]}||segment`) : s) : '';
const Bars = ({ rows, total, t }: { rows: [string, number][]; total?: number; t?: { lang?: string } }) => { const max = Math.max(1, ...rows.map(r => r[1])); return <ul className="bars">{rows.map(([k, v]) => <li key={k}><span>{k}</span><i><em style={{ width: Math.max(2, v / max * 100) + '%' }} /></i><b>{v.toLocaleString(locale(t))}{total ? <small> · {Math.round(v / total * 100)}%</small> : null}</b></li>)}</ul>; };

async function Buyers(sp: Record<string, string | undefined>) {
  if (sp.company) return BuyerCompany(sp.company);
  if (sp.find) return FindBuyers(sp.find, sp.lang === 'en' ? 'en' : 'nl');
  const t = await lang();
  const qs = new URLSearchParams(Object.entries({ q: sp.q, segment: sp.segment, stage: sp.stage, contacts: sp.contacts, sort: sp.sort }).filter(([, v]) => v) as [string, string][]);
  const r = await api(`/admin/buyers?${qs}`); if (!r.ok) return <Denied r={r} t={t} />; const d = r.data; const s = d.stats;
  return <div className="buyers">
    <div className="access-top"><div><p className="eyebrow">{t('BUY SIDE · POTENTIAL BUYERS')}</p><h2>{t('Who buys what we sell.')}</h2><p className="muted-small">{t('Companies from the Kadaster ownership exports, with their portfolios and buying activity. Pick a property to see the best-matching buyers and email them a personal invitation.')}</p></div>
      <ListingSwitch listings={d.listings} /></div>
    <div className="stat-row five"><div><b>{s.companies.toLocaleString(locale(t))}</b><span>{t('Companies')}</span></div><div><b>{s.buildings.toLocaleString(locale(t))}</b><span>{t('Buildings in the data')}</span></div><div><b>{s.withContacts}<small> / {s.companies}</small></b><span>{t('Companies with an email contact')}</span></div><div><b>{s.sent.toLocaleString(locale(t))}</b><span>{t('Emails sent')}{s.queued ? ` · ${t('{n} queued', { n: s.queued })}` : ''}</span></div><div><b>{s.registered}</b><span>{t('Registered via email')}</span></div></div>
    <div className="buyers-top"><ImportBox />
      <div className="panel"><p className="eyebrow">{t('RECENT IMPORTS')}</p>{d.imports.length ? <ul className="log">{d.imports.map((i: any) => <li key={i.id}><b>{i.fileName}</b> · {t(`${i.kind}||import`)}{i.status === 'failed' ? <span className="form-error"> · {t('failed: {error}', { error: i.error })}</span> : i.status !== 'done' ? ` · ${t(`${i.status}||import`)}…` : ` · ${t('{rows} rows, {created} new, {updated} updated', { rows: i.rows.toLocaleString(locale(t)), created: i.created.toLocaleString(locale(t)), updated: i.updated.toLocaleString(locale(t)) })}`}<small>{dateTime(i.createdAt, t)}</small></li>)}</ul> : <p className="muted-small">{t('Nothing imported yet. Start with the three exports: properties, owners and owner_properties. Then add contact persons (company, name, email) with the contacts template.')}</p>}
        <p className="fine-print">{t('Natural persons stay anonymous in the exports and are never imported as buyers. Contact persons are personal data (AVG): keep only business contacts, honour every unsubscribe and delete a person on request.')}</p></div></div>
    <form className="filters-row" action="/admin"><input type="hidden" name="tab" value="buyers" /><label className="search-in"><Icon name="search" /><input name="q" defaultValue={sp.q} placeholder={t('Company, legal entity or city')} aria-label={t('Search')} /></label>
      <select name="segment" defaultValue={sp.segment || ''} aria-label={t('Segment')}><option value="">{t('Every segment')}</option>{d.segments.map((x: string) => <option key={x} value={x}>{seg(t, x)}</option>)}</select>
      <select name="stage" defaultValue={sp.stage || ''} aria-label={t('Stage')}><option value="">{t('Every stage')}</option>{d.stages.map(([k, l]: [string, string]) => <option key={k} value={k}>{t(l)}</option>)}</select>
      <select name="contacts" defaultValue={sp.contacts || ''} aria-label={t('Contacts')}><option value="">{t('With or without contact')}</option><option value="with">{t('With email contact')}</option><option value="without">{t('Without email contact')}</option></select>
      <select name="sort" defaultValue={sp.sort || 'buildings'} aria-label={t('Sort')}><option value="buildings">{t('Most buildings')}</option><option value="recent">{t('Latest purchase')}</option><option value="m2">{t('Most m²')}</option><option value="name">{t('Name')}</option></select>
      <button className="btn navy small">{t('Filter')}</button></form>
    {d.companies.length ? <div className="table-wrap" tabIndex={0}><table className="buyers-table"><thead><tr><th>{t('Company')}</th><th>{t('Buildings')}</th><th>{t('Floor area')}</th><th>{t('Residential')}</th><th>{t('Largest deal')}</th><th>{t('Latest purchase')}</th><th>{t('Segment')}</th><th>{t('Contacts')}</th><th>{t('Stage')}</th></tr></thead><tbody>
      {d.companies.map((c: any) => <tr key={c.id}><td><Link href={`/admin?tab=buyers&company=${c.id}`}><b>{c.name}</b></Link><small>{c.cities.join(', ')}{c.citiesCount > c.cities.length ? ` +${c.citiesCount - c.cities.length}` : ''}</small></td><td>{c.buildings.toLocaleString(locale(t))}<small>{t('{n} in last 5 yrs', { n: c.recentCount })}</small></td><td>{c.totalM2 ? c.totalM2.toLocaleString(locale(t)) + ' m²' : '—'}</td><td>{pct(c.residentialShare)}</td><td>{moneyShort(c.maxDeal)}</td><td>{date(c.lastPurchase, t)}{c.recent12m ? <small>{t('{n} in last 12 months', { n: c.recent12m })}</small> : null}</td><td>{seg(t, c.segment) || '—'}</td>
        <td>{c.doNotContact ? <span className="status-chip expired"><i />{t('Do not contact')}</span> : c.emailable ? <span className="status-chip active"><i />{t(c.emailable > 1 ? '{n} emails' : '{n} email', { n: c.emailable })}</span> : <Link className="link-button" href={`/admin?tab=buyers&company=${c.id}#contacts`}>{t('Add contact')}</Link>}{c.lastEmailAt && <small>{t('Emailed {date}', { date: date(c.lastEmailAt, t) })}</small>}</td><td>{STAGE_LABEL[c.stage] ? t(STAGE_LABEL[c.stage]) : c.stage}</td></tr>)}</tbody></table></div>
      : <div className="empty"><p>{s.companies ? t('No company matches these filters.') : t('No buyers yet. Import the ownership exports above.')}</p></div>}
    <ActionForm action="/api/admin/buyers/companies" className="panel add-company" success={t('Company added. Open it to add contact persons.')} submitLabel={t('Add company ↗')}><p className="eyebrow">{t('A BUYER THAT IS NOT IN THE EXPORTS')}</p><label>{t('Company name')}<input name="name" required minLength={2} maxLength={160} placeholder={t('For example a fund you met at an event')} /></label></ActionForm>
  </div>;
}

async function FindBuyers(id: string, lng: 'nl' | 'en') {
  const t = await lang();
  const [r, o, ac] = await Promise.all([api(`/admin/buyers/match/${id}?lang=${lng}&limit=200`), api('/admin/buyers'), api('/admin/access')]); if (!r.ok) return <Denied r={r} t={t} />; const l = r.data.listing;
  const access = ac.ok ? { listings: ac.data.listings.filter((x: any) => !['sold', 'withdrawn', 'draft'].includes(x.status)), features: ac.data.features, presets: ac.data.presets } : { listings: [], features: [], presets: [] };
  return <div className="buyers">
    <div className="access-top"><div><p className="eyebrow"><Link href="/admin?tab=buyers">{t('BUYERS')}</Link> · {t('POTENTIAL BUYERS')}</p><h2>{l.name}</h2><p className="muted-small">{l.city} · {t(l.propertyType)}{l.units > 1 ? ` · ${t('{n} units', { n: l.units })}` : ''} · {l.priceOnRequest ? t('price on request') : moneyShort(l.askingPrice)} · {t(`${l.status.replace('_', ' ')}||listing`)} · <Link href={`/listings/${l.slug}`}>{t('open listing ↗')}</Link></p></div>
      {o.ok && <ListingSwitch listings={o.data.listings} current={l.id} />}</div>
    <BuyerFinder key={lng} data={r.data} lang={lng} access={access} />
  </div>;
}

async function BuyerCompany(id: string) {
  const t = await lang();
  const r = await api(`/admin/buyers/${id}`); if (!r.ok) return <Denied r={r} t={t} />; const c = r.data; const p = c.profile;
  const usesTotal = Object.values(p.uses || {}).reduce((a: number, b: any) => a + b, 0) as number;
  return <div className="buyers company">
    <div className="access-top"><div><p className="eyebrow"><Link href="/admin?tab=buyers">{t('BUYERS')}</Link> · {(seg(t, c.segment) || t('COMPANY')).toUpperCase()}</p><h2>{c.name}</h2><p className="muted-small">{c.legalEntities.length ? c.legalEntities.join(' · ') : t('No Kadaster entities recorded')}</p></div>
      <label className="listing-switch"><span>{t('Stage')}</span><PatchSelect url={`/api/admin/buyers/${c.id}`} field="stage" value={c.stage} label={t('Stage')} options={c.stages.map(([k, l]: [string, string]) => [k, t(l)] as [string, string])} /></label></div>
    <div className="stat-row five"><div><b>{c.buildings.toLocaleString(locale(t))}</b><span>{t('Buildings')}</span></div><div><b>{c.totalM2 ? (c.totalM2 / 1000).toLocaleString('en', { maximumFractionDigits: 0 }) + 'k' : '—'}<small> m²</small></b><span>{t('Floor area')}</span></div><div><b>{c.recentCount}</b><span>{t('Bought in the last 5 years')}</span></div><div><b>{date(c.lastPurchase, t)}</b><span>{t('Latest purchase')}</span></div><div><b>{moneyShort(p.maxDeal)}</b><span>{t('Largest deal · typical {amount}', { amount: moneyShort(p.medianDeal) })}</span></div></div>
    <div className="three-panels">
      <div className="panel"><p className="eyebrow">{t('WHERE THEY OWN')}</p>{p.topCities?.length ? <Bars t={t} rows={p.topCities} /> : <p className="muted-small">{c.allCities.join(', ') || t('No buildings linked yet.')}</p>}{p.recentCities?.length > 0 && <><p className="eyebrow sub">{t('BOUGHT IN THE LAST 5 YEARS')}</p><div className="chips">{p.recentCities.map(([k, v]: [string, number]) => <span key={k} className="chip">{k} · {v}</span>)}</div></>}</div>
      <div className="panel"><p className="eyebrow">{t('WHAT THEY OWN')}</p>{usesTotal ? <Bars t={t} rows={Object.entries(p.uses).sort((a: any, b: any) => b[1] - a[1]).map(([k, v]) => [USE[k] ? t(`${USE[k]}||use`) : k, v as number])} total={usesTotal} /> : <p className="muted-small">{t('No building data linked.')}</p>}
        <dl className="facts compact"><div><dt>{t('Typical floor area')}</dt><dd>{p.medianFloorM2 ? p.medianFloorM2 + ' m²' : '—'}</dd></div><div><dt>{t('Typical build year')}</dt><dd>{p.medianBuildYear || '—'}</dd></div><div><dt>{t('Investment purchases')}</dt><dd>{p.investmentDeals ?? 0}</dd></div><div><dt>{t('Development · forward funding')}</dt><dd>{p.developmentDeals ?? 0}</dd></div></dl></div>
      <div className="panel" id="contacts"><p className="eyebrow">{t('CONTACT PERSONS')}</p>{c.contactList.length ? <ul className="contacts">{c.contactList.map((x: any) => <li key={x.id} className={x.unsubscribedAt ? 'off' : ''}><span className="avatar-sm">{x.name.split(' ').map((w: string) => w[0]).join('').slice(0, 2).toUpperCase()}</span><div><b>{x.name}</b><small>{[x.role, x.email, x.phone, x.language.toUpperCase()].filter(Boolean).join(' · ')}</small>{x.unsubscribedAt && <small className="form-error">{t('Unsubscribed {date}', { date: date(x.unsubscribedAt, t) })}</small>}</div>
          <span className="row tight">{x.unsubscribedAt ? <ActionButton url={`/api/admin/buyers/contacts/${x.id}`} method="PATCH" json={{ unsubscribed: false }} label={t('Resubscribe')} confirmText={t('Only resubscribe when this person asked for it. Continue?')} /> : null}<ActionButton url={`/api/admin/buyers/contacts/${x.id}`} method="DELETE" label={t('Delete')} confirmText={t('Delete {name} and their email history? Use this for erasure requests.', { name: x.name })} /></span></li>)}</ul> : <p className="muted-small">{t('No contact person yet. Add one to email this company.')}</p>}
        <ActionForm action={`/api/admin/buyers/${c.id}/contacts`} className="contact-form" success={t('Contact added.')} submitLabel={t('Add contact ↗')}><div className="form-grid"><label>{t('Name')}<input name="name" required minLength={2} maxLength={120} /></label><label>{t('Role')}<input name="role" maxLength={120} placeholder={t('Head of Acquisitions')} /></label><label>{t('Email')}<input name="email" type="email" maxLength={160} /></label><label>{t('Phone')}<input name="phone" maxLength={40} /></label><label>{t('Language')}<select name="language"><option value="nl">Nederlands</option><option value="en">English</option></select></label></div></ActionForm>
        <DoNotContact id={c.id} on={c.doNotContact} /></div></div>
    <ActionForm action={`/api/admin/buyers/${c.id}`} method="PATCH" className="panel notes-form" success={t('Notes saved.')} submitLabel={t('Save notes')}><p className="eyebrow">{t('NOTES')}</p><textarea name="notes" defaultValue={c.notes || ''} maxLength={4000} aria-label={t('Notes')} placeholder={t('What they buy, who decides, last conversation…')} /></ActionForm>
    {c.history.length > 0 && <><div className="section-heading" style={{ marginTop: 40 }}><div><p className="eyebrow">{t('EMAILS')}</p><h2>{t('Outreach history.')}</h2></div></div><div className="table-wrap" tabIndex={0}><table><thead><tr><th>{t('Property')}</th><th>{t('To')}</th><th>{t('Status')}</th><th>{t('Sent')}</th><th>{t('Opened')}</th><th>{t('Clicked')}</th><th>{t('Registered')}</th></tr></thead><tbody>{c.history.map((h: any) => <tr key={h.id}><td>{h.listing}</td><td>{h.toEmail}</td><td><span className={`pill out-${h.status}`}>{t(`${h.status}||mail`)}</span></td><td>{dateTime(h.sentAt, t)}</td><td>{dateTime(h.openedAt, t)}</td><td>{dateTime(h.clickedAt, t)}</td><td>{dateTime(h.acceptedAt, t)}</td></tr>)}</tbody></table></div></>}
    <div className="section-heading" style={{ marginTop: 40 }}><div><p className="eyebrow">{t('PORTFOLIO · LATEST {n} OF {total}', { n: c.holdings.length, total: c.buildings.toLocaleString(locale(t)) })}</p><h2>{t('Buildings.')}</h2></div><span>{t('Source: {file}', { file: c.sourceFile || '—' })}</span></div>
    {c.holdings.length ? <div className="table-wrap" tabIndex={0}><table><thead><tr><th>{t('Address')}</th><th>{t('Use')}</th><th>{t('Floor area')}</th><th>{t('Built')}</th><th>{t('Bought')}</th><th>{t('Price band')}</th><th>{t('Transaction')}</th><th><span className="sr-only">{t('Factsheet')}</span></th></tr></thead><tbody>{c.holdings.map((h: any) => <tr key={h.bagId}><td><b>{h.address || t('Several addresses')}</b><small>{h.city} · BAG {h.bagId}</small></td><td>{h.use || '—'}</td><td>{h.floorM2 ? h.floorM2.toLocaleString(locale(t)) + ' m²' : '—'}</td><td>{h.buildYear || '—'}</td><td>{date(h.purchaseDate, t)}</td><td>{h.priceBand || '—'}</td><td>{h.transactionType || '—'}</td><td>{h.factsheet ? <a className="link-button" href={h.factsheet} target="_blank" rel="noopener noreferrer">{t('Factsheet ↗')}</a> : null}</td></tr>)}</tbody></table></div> : <div className="empty"><p>{t('No buildings linked. Import the owner_properties export.')}</p></div>}
  </div>;
}

const FUNNEL: [string, string][] = [['sent', 'Sent'], ['opened', 'Opened'], ['clicked', 'Clicked'], ['registered', 'Registered']];
const Funnel = ({ f, t }: { f: any; t: T }) => <div className="ofunnel">{FUNNEL.map(([k, l]) => <div key={k}><span>{t(l)}</span><b>{f[k]}</b><i><em style={{ width: (f.total ? f[k] / f.total * 100 : 0) + '%' }} /></i></div>)}</div>;

async function Outreach(sp: Record<string, string | undefined>) {
  if (sp.campaign) return Campaign(sp.campaign);
  const t = await lang();
  const [r, ob] = await Promise.all([api('/admin/outreach'), api('/admin/outbox')]); if (!r.ok) return <Denied r={r} t={t} />; const d = r.data; const tot = d.totals;
  const outbox = (ob.ok ? ob.data : []).filter((m: any) => m.kind === 'outreach').slice(0, 15);
  return <div className="buyers">
    <div className="access-top"><div><p className="eyebrow">{t('EMAIL OUTREACH')}</p><h2>{t('Who opened, who came in.')}</h2><p className="muted-small">{t('Each email carries a personal link. Opening it creates that person’s invitation with access to the property in the email only.')}</p></div>
      <div className="row wrap">{tot.queued > 0 && <ActionButton url="/api/admin/outreach/send-now" label={<><Icon name="mail" />{t('Send {n} queued now', { n: tot.queued })}</>} className="btn navy small" done={t('Sent.')} />}<Link className="btn outline small" href="/admin?tab=buyers">{t('Find buyers ↗')}</Link></div></div>
    <div className={`mail-mode ${d.mail.mode}`}><Icon name={d.mail.mode === 'smtp' ? 'check' : 'bolt'} />{d.mail.mode === 'smtp' ? <span>{t('Connected to')} <b>{d.mail.host}</b> · {t('sending as {from} · {n} emails every 30 seconds.', { from: d.mail.from, n: d.mail.perTick })}</span> : <span><b>{t('Simulated sending.')}</b> {t('No mail server is connected, so emails go to the outbox (Automation tab) instead of the inbox. Set SMTP_HOST, SMTP_USER, SMTP_PASSWORD and MAIL_FROM on the server to send for real.')}</span>}</div>
    <div className="stat-row five"><div><b>{tot.sent}</b><span>{t('Sent')}{tot.queued ? ` · ${t('{n} queued', { n: tot.queued })}` : ''}</span></div><div><b>{tot.opened}</b><span>{t('Opened')}{tot.sent ? ` · ${Math.round(tot.opened / tot.sent * 100)}%` : ''}</span></div><div><b>{tot.clicked}</b><span>{t('Clicked the link')}</span></div><div><b>{tot.registered}</b><span>{t('Created an account')}</span></div><div><b>{tot.unsubscribed}</b><span>{t('Unsubscribed')}{tot.failed ? ` · ${t('{n} failed', { n: tot.failed })}` : ''}</span></div></div>
    {d.campaigns.length ? <div className="campaigns">{d.campaigns.map((c: any) => <Link key={c.id} href={`/admin?tab=outreach&campaign=${c.id}`} className="campaign"><div><p className="eyebrow">{c.language.toUpperCase()} · {dateTime(c.createdAt, t)} · {c.sender}</p><h3>{c.listing}</h3><p className="muted-small">{c.subject}</p></div><div className="camp-side"><b>{c.funnel.total}</b><span>{t('emails')}{c.funnel.queued ? ` · ${t('{n} queued', { n: c.funnel.queued })}` : ''}</span></div><Funnel f={c.funnel} t={t} /></Link>)}</div>
      : <div className="empty"><p>{t('No emails yet. Open Buyers, choose a property and select the companies to email.')}</p><Link className="btn navy small" href="/admin?tab=buyers">{t('Find buyers ↗')}</Link></div>}
    {d.mail.mode !== 'smtp' && outbox.length > 0 && <div className="panel"><p className="eyebrow">{t('OUTBOX · SIMULATED, NOT DELIVERED')}</p><h2>{t('What the buyers would receive.')}</h2><p className="muted-small">{t('Open an email to read it. The links in it work: open one in a private window to see the buyer’s side.')}</p>{outbox.map((m: any) => <details key={m.id} className="document-row"><summary>{m.subject}<small>{t('To {email} · {date}', { email: m.toEmail, date: dateTime(m.createdAt, t) })}</small></summary><pre className="mail-body">{m.body}</pre></details>)}</div>}
  </div>;
}

async function Campaign(id: string) {
  const t = await lang();
  const r = await api(`/admin/outreach/${id}`); if (!r.ok) return <Denied r={r} t={t} />; const c = r.data;
  const nf = c.grant.featureLabels.length;
  return <div className="buyers">
    <div className="access-top"><div><p className="eyebrow"><Link href="/admin?tab=outreach">{t('OUTREACH')}</Link> · {c.language.toUpperCase()} · {dateTime(c.createdAt, t)}</p><h2>{c.listing}</h2><p className="muted-small">{c.subject} · {t('by {name}', { name: c.sender })}</p></div>
      <div className="row wrap">{c.funnel.queued > 0 && <><ActionButton url="/api/admin/outreach/send-now" label={t('Send queued now')} className="btn navy small" done={t('Sent.')} /><ActionButton url={`/api/admin/outreach/${c.id}/cancel`} label={t('Cancel queued')} confirmText={t('Cancel every email of this campaign that has not been sent yet?')} /></>}{c.funnel.failed > 0 && <ActionButton url={`/api/admin/outreach/${c.id}/retry`} label={t('Retry {n} failed', { n: c.funnel.failed })} />}</div></div>
    <div className="grant-sum wide"><div><p className="eyebrow">{t('THE LINK IN THESE EMAILS GIVES')}</p><b>{c.grant.scope === 'all' ? t('All properties') : c.grant.listings.join(' · ')}</b><small>{t(nf === 1 ? '{n} feature: {list}' : '{n} features: {list}', { n: nf, list: c.grant.featureLabels.map((x: string) => t(x)).join(', ') || t('none||features') })}</small></div></div>
    <Funnel f={c.funnel} t={t} />
    <div className="table-wrap" tabIndex={0}><table><thead><tr><th>{t('Company')}</th><th>{t('Contact')}</th><th>{t('Match')}</th><th>{t('Status')}</th><th>{t('Sent')}</th><th>{t('Opened')}</th><th>{t('Clicked')}</th><th>{t('Registered')}</th><th>{t('Viewed · offers')}</th></tr></thead><tbody>{c.messages.map((m: any) => <tr key={m.id}><td><Link href={`/admin?tab=buyers&company=${m.companyId}`}><b>{m.company}</b></Link></td><td>{m.contact}<small>{m.email}</small></td><td>{m.score ?? '—'}</td><td><span className={`pill out-${m.unsubscribedAt ? 'unsubscribed' : m.status}`}>{t(`${m.unsubscribedAt ? 'unsubscribed' : m.status}||mail`)}</span>{m.error && <small className="form-error">{m.error}</small>}</td><td>{dateTime(m.sentAt, t)}</td><td>{dateTime(m.openedAt, t)}</td><td>{dateTime(m.clickedAt, t)}</td><td>{dateTime(m.registeredAt, t)}</td><td>{m.views} · {m.offers}</td></tr>)}</tbody></table></div>
    <details className="panel payload"><summary><span><p className="eyebrow">{t('TEMPLATE')}</p><h2>{t('The message as written.')}</h2></span><span className="text-link">{t('Show')}</span></summary><pre className="code">{c.body}</pre></details>
  </div>;
}

async function Settings() {
  const t = await lang();
  const r = await api('/admin/workspace'); if (!r.ok) return <Denied r={r} t={t} />;
  return <div className="buyers"><div className="access-top"><div><p className="eyebrow">{t('DEVELOPER · WORKSPACE')}</p><h2>{t('Which sections admins see.')}</h2><p className="muted-small">{t('Switch off what the team does not use yet. Nothing is deleted: switch a section back on and everything in it is still there. You always see every section; hidden ones are dimmed in the tab bar.')}</p></div></div>
    <WorkspaceTabs tabs={r.data.tabs} /></div>;
}
